1	# TikTok content analysis POC (经营计划 P2.0) — 视频概览 + 商品卡
2	# 默认只写 logs/*-debug-*.json，不上报中心 fact（门禁前不建表）。
3	#
4	# Usage:
5	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1
6	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1 -ConfigPath .\config\stores.config.deal-only.json
7	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1 -Modules content_overview,product_traffic -ListOnly
8	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1 -Modules content_probe
9	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1 -Modules video_list
10	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1 -SkipIngest:$false
11	#
12	# Requires: Ziniao + Bridge. URLs: config.contentUrl / productTrafficUrl / videoListUrl.
13	
14	param(
15	  [string]$ConfigPath = "",
16	  [switch]$ListOnly,
17	  [string]$DryRun = "",
18	  [string]$DateMode = "",
19	  [string]$Modules = "content_overview,product_traffic",
20	  [switch]$SkipIngest = $true
21	)
22	
23	$ErrorActionPreference = 'Stop'
24	$PSNativeCommandUseErrorActionPreference = $false
25	$root = Split-Path $PSScriptRoot -Parent
26	if (-not $ConfigPath) { $ConfigPath = Join-Path $root 'config\stores.config.json' }
27	if (-not (Test-Path $ConfigPath)) { throw "Missing config: $ConfigPath" }
28	
29	$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
30	$qingquanLib = Join-Path $PSScriptRoot 'qingquan-client.ps1'
31	if (Test-Path $qingquanLib) { . $qingquanLib }
32	$ziniaoWinLib = Join-Path $PSScriptRoot 'ziniao-window.ps1'
33	if (-not (Test-Path $ziniaoWinLib)) { throw "Missing $ziniaoWinLib" }
34	. $ziniaoWinLib
35	
36	$script:logsDir = Join-Path $root 'logs'
37	New-Item -ItemType Directory -Force -Path $script:logsDir | Out-Null
38	$script:runStamp = Get-Date -Format 'yyyyMMdd-HHmmss'
39	$script:runLogFile = Join-Path $script:logsDir ("content-poc-run-{0}.log" -f $script:runStamp)
40	
41	function Write-RunLog([string]$msg) {
42	  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
43	  try { Add-Content -LiteralPath $script:runLogFile -Value $line -Encoding UTF8 } catch { }
44	}
45	function Write-Step([string]$msg) {
46	  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
47	  Write-RunLog $msg
48	}
49	
50	function Write-Utf8File([string]$Path, [string]$Content) {
51	  if ([string]::IsNullOrWhiteSpace($Path)) { throw "Write-Utf8File: Path is empty" }
52	  $dir = Split-Path -Parent $Path
53	  if ($dir -and -not (Test-Path -LiteralPath $dir)) {
54	    New-Item -ItemType Directory -Force -Path $dir | Out-Null
55	  }
56	  $text = if ($null -eq $Content) { '' } else { [string]$Content }
57	  [System.IO.File]::WriteAllText($Path, $text, [System.Text.UTF8Encoding]::new($false))
58	}
59	function ConvertTo-ProcessArgument([string]$s) {
60	  if ($null -eq $s) { return '""' }
61	  if ($s -match '[\s"]') { return '"' + ($s -replace '"', '\"') + '"' }
62	  return $s
63	}
64	function Initialize-ZiniaoCli {
65	  if ($script:ZiniaoNode) { return }
66	  $node = (Get-Command node -ErrorAction SilentlyContinue).Source
67	  if (-not $node) { throw 'node not found' }
68	  $runJs = Join-Path $env:APPDATA 'npm\node_modules\@ziniao-open\cli\scripts\run.js'
69	  if (-not (Test-Path $runJs)) {
70	    $cmd = Get-Command ziniao -ErrorAction SilentlyContinue
71	    if ($cmd) { $runJs = $cmd.Source }
72	  }
73	  if (-not (Test-Path $runJs)) { throw 'ziniao-cli run.js not found' }
74	  $script:ZiniaoNode = $node
75	  $script:ZiniaoRunJs = $runJs
76	}
77	function Invoke-Ziniao([string[]]$CliArgs) {
78	  Initialize-ZiniaoCli
79	  $utf8 = [System.Text.UTF8Encoding]::new($false)
80	  $allArgs = @($script:ZiniaoRunJs) + @($CliArgs)
81	  $argLine = ($allArgs | ForEach-Object { ConvertTo-ProcessArgument ([string]$_) }) -join ' '
82	  $psi = New-Object System.Diagnostics.ProcessStartInfo
83	  $psi.FileName = $script:ZiniaoNode
84	  $psi.Arguments = $argLine
85	  $psi.UseShellExecute = $false
86	  $psi.RedirectStandardOutput = $true
87	  $psi.RedirectStandardError = $true
88	  $psi.CreateNoWindow = $true
89	  $psi.StandardOutputEncoding = $utf8
90	  $psi.StandardErrorEncoding = $utf8
91	  $p = New-Object System.Diagnostics.Process
92	  $p.StartInfo = $psi
93	  [void]$p.Start()
94	  $stdout = $p.StandardOutput.ReadToEnd()
95	  $stderr = $p.StandardError.ReadToEnd()
96	  $p.WaitForExit()
97	  if ($stderr) { Write-Host $stderr }
98	  return $stdout
99	}
100	function ConvertTo-ScrapeOneLine([string]$js) {
101	  return (($js -replace '(?m)^\s*//.*$', '' -replace '\r?\n', ' ' -replace '\s+', ' ').Trim())
102	}
103	function Get-ScrapePayload([string]$execOut) {
104	  if ([string]::IsNullOrWhiteSpace($execOut)) { return $null }
105	  try {
106	    $j = $execOut | ConvertFrom-Json
107	    if ($j.data -and $j.data.data -and $j.data.data.result) {
108	      return ([string]$j.data.data.result | ConvertFrom-Json)
109	    }
110	    if ($null -ne $j.ok) { return $j }
111	  } catch { }
112	  $m = [regex]::Matches($execOut, '\{(?:[^{}]|(?<o>\{)|(?<-o>\}))+(?(o)(?!))\}')
113	  if ($m.Count -gt 0) {
114	    try { return ($m[$m.Count - 1].Value | ConvertFrom-Json) } catch { }
115	  }
116	  return $null
117	}
118	function Convert-DryRunFlag([string]$raw) {
119	  if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
120	  switch -Regex ($raw.Trim()) {
121	    '^(?i:true|1|yes|y|\$true)$'  { return $true }
122	    '^(?i:false|0|no|n|\$false)$' { return $false }
123	    default { throw "Invalid -DryRun '$raw'" }
124	  }
125	}
126	function Get-DisplayName($store, $map) {
127	  $n = [string]$store.storeName
128	  if ($map -and $map.PSObject.Properties.Name -contains $n) { return [string]$map.$n }
129	  return $n
130	}
131	function Test-BridgeAlive {
132	  try {
133	    $null = Invoke-WebRequest -Uri 'http://127.0.0.1:9481' -TimeoutSec 3 -UseBasicParsing -ErrorAction Stop
134	    return $true
135	  } catch {
136	    # Bridge often returns 401 without auth — still means process is up
137	    $msg = [string]$_.Exception.Message
138	    if ($msg -match '401|403|Unauthorized|Forbidden') { return $true }
139	    return $false
140	  }
141	}
142	
143	function Invoke-EnsurePageReady {
144	  param(
145	    [string]$StoreId,
146	    [string]$TargetUrl,
147	    [string]$UrlCheckOneLiner,
148	    [int]$MaxTries = 3
149	  )
150	  for ($t = 1; $t -le $MaxTries; $t++) {
151	    if (-not (Test-BridgeAlive)) {
152	      Write-Step ("  bridge down try {0}/{1}, wait 15s..." -f $t, $MaxTries)
153	      Start-Sleep -Seconds 15
154	      if (-not (Test-BridgeAlive)) {
155	        if ($t -eq $MaxTries) { return @{ ok = $false; error = 'bridge unreachable' } }
156	        continue
157	      }
158	    }
159	    try {
160	      $null = Invoke-Ziniao @('page', 'visit', '--store-id', $StoreId, '--url', $TargetUrl, '--wait-until', 'load', '--timeout', '120000')
161	    } catch {
162	      Write-Step ("  visit error try {0}: {1}" -f $t, $_)
163	      Start-Sleep -Seconds 8
164	      continue
165	    }
166	    Start-Sleep -Seconds 8
167	    $chkOut = ''
168	    try {
169	      $chkOut = Invoke-Ziniao @('page', 'exec', '--store-id', $StoreId, '--script', $UrlCheckOneLiner, '--timeout', '30000')
170	    } catch {
171	      Write-Step ("  url-check exec fail try {0}: {1}" -f $t, $_)
172	      Start-Sleep -Seconds 10
173	      continue
174	    }
175	    $chk = Get-ScrapePayload $chkOut
176	    $href = ''
177	    if ($chk -and $chk.href) { $href = [string]$chk.href }
178	    $blank = $false
179	    if ($chk -and $chk.blank) { $blank = [bool]$chk.blank }
180	    if (-not $href -or $href -match 'about:blank' -or $blank) {
181	      Write-Step ("  page not ready try {0}/{1}: href={2}" -f $t, $MaxTries, $href)
182	      Start-Sleep -Seconds 12
183	      continue
184	    }
185	    # Wrong landing: content-analysis/* or video-analytics/overview often bounce to data-overview
186	    if ($href -match 'data-overview' -and $TargetUrl -notmatch 'data-overview') {
187	      Write-Step ("  landed data-overview (want {0}), retry visit..." -f $TargetUrl)
188	      Start-Sleep -Seconds 5
189	      continue
190	    }
191	    $bodyLen = 0
192	    if ($chk -and $chk.bodyLen) { $bodyLen = [int]$chk.bodyLen }
193	    # video-details SPA: shell chrome ~200-400 chars until table hydrates (2026-08-05 deep POC)
194	    if ($TargetUrl -match 'video-details|video-analytics/detail' -and $bodyLen -gt 0 -and $bodyLen -lt 800) {
195	      Write-Step ("  video-details shell only bodyLen={0}, wait hydrate try {1}/{2}..." -f $bodyLen, $t, $MaxTries)
196	      Start-Sleep -Seconds 28
197	      $chk2Out = ''
198	      try {
199	        $chk2Out = Invoke-Ziniao @('page', 'exec', '--store-id', $StoreId, '--script', $UrlCheckOneLiner, '--timeout', '30000')
200	      } catch { }

